import { useEffect, useState } from 'react';
import API from '../services/api';

const ROLES = ['Admin', 'Record Manager', 'Authorized User', 'Auditor'];

export default function Users() {
  const [users, setUsers] = useState([]);
  const [message, setMessage] = useState('');

  const loadUsers = async () => {
    const { data } = await API.get('/auth/users');
    setUsers(data);
  };

  useEffect(() => {
    loadUsers().catch(() => setMessage('Unable to load users.'));
  }, []);

  const updateUserRole = async (userId, role) => {
    try {
      await API.put(`/auth/users/${userId}`, { role });
      setMessage('User role updated.');
      loadUsers();
    } catch (err) {
      setMessage(err.response?.data?.message || 'Unable to update role.');
    }
  };

  const updateUsername = async (userId, username) => {
    try {
      await API.put(`/auth/users/${userId}`, { username });
      setMessage('Username updated.');
      loadUsers();
    } catch (err) {
      setMessage(err.response?.data?.message || 'Unable to update username.');
    }
  };

  return (
    <div className="page-shell">
      <section className="page-header">
        <div>
          <span className="eyebrow">Administration</span>
          <h1>Users</h1>
          <p>Assign roles, maintain usernames, and manage DRMS access control from one place.</p>
        </div>
      </section>

      {message && <div className="message message--info">{message}</div>}

      <section className="panel">
        <div className="table-scroll">
          <table className="data-table">
            <thead>
              <tr>
                <th>Name</th>
                <th>Username</th>
                <th>Email</th>
                <th>Role</th>
                <th>Update</th>
              </tr>
            </thead>
            <tbody>
              {users.map((user) => (
                <tr key={user._id}>
                  <td>{user.name}</td>
                  <td>{user.username || '-'}</td>
                  <td>{user.email}</td>
                  <td>{user.role}</td>
                  <td>
                    <div className="stack">
                      <input
                        className="input"
                        defaultValue={user.username || ''}
                        onBlur={(e) => {
                          const nextValue = e.target.value.trim();
                          if (nextValue && nextValue !== user.username) {
                            updateUsername(user._id, nextValue);
                          }
                        }}
                      />
                      <select className="input" value={user.role} onChange={(e) => updateUserRole(user._id, e.target.value)}>
                        {ROLES.map((role) => <option key={role} value={role}>{role}</option>)}
                      </select>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </div>
  );
}
